using System.Diagnostics;
namespace CMCutLab;
internal sealed class RenderPanel:UserControl
{
 readonly Label heading=new(){AutoSize=true},metrics=new(){AutoSize=true},processed=new(){AutoSize=true},settings=new(){AutoSize=true},destination=new(){AutoEllipsis=true,Dock=DockStyle.Fill},failure=new(){AutoSize=true,ForeColor=Color.Salmon};readonly ProgressBar bar=new(){Dock=DockStyle.Fill,Maximum=1000};readonly Button cancel=new(){Text="レンダリングをキャンセル",AutoSize=true},reveal=new(){Text="出力先を開く",AutoSize=true},close=new(){Text="閉じる",AutoSize=true};readonly System.Windows.Forms.Timer timer=new(){Interval=250};RenderJob? job;
 internal event Action? CancelRequested,CloseRequested;
 internal RenderPanel(){Dock=DockStyle.Fill;BackColor=Color.FromArgb(33,36,40);Padding=new Padding(10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=7};foreach(int height in new[]{30,18,27,27,27,28,36})layout.RowStyles.Add(new(SizeType.Absolute,height));Controls.Add(layout);heading.Font=new Font(SystemFonts.MessageBoxFont.FontFamily,13,FontStyle.Bold);layout.Controls.Add(heading,0,0);layout.Controls.Add(bar,0,1);layout.Controls.Add(metrics,0,2);layout.Controls.Add(processed,0,3);layout.Controls.Add(settings,0,4);layout.Controls.Add(destination,0,5);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};buttons.Controls.AddRange([cancel,reveal,close,failure]);layout.Controls.Add(buttons,0,6);foreach(var b in new[]{cancel,reveal,close}){b.FlatStyle=FlatStyle.Flat;b.ForeColor=Color.White;b.BackColor=Color.FromArgb(65,70,76);}cancel.BackColor=Color.FromArgb(154,66,48);cancel.Click+=(_,_)=>{if(job?.Snapshot().Active==true){job.Cancelling();cancel.Enabled=false;RefreshJob();CancelRequested?.Invoke();}};close.Click+=(_,_)=>CloseRequested?.Invoke();reveal.Click+=(_,_)=>{if(job!=null)Process.Start(new ProcessStartInfo("explorer.exe"){UseShellExecute=true,ArgumentList={Path.GetDirectoryName(job.Output)!}});};timer.Tick+=(_,_)=>RefreshJob();Disposed+=(_,_)=>timer.Dispose();}
 internal void Attach(RenderJob value){job=value;timer.Start();RefreshJob();}
 static string Time(TimeSpan t)=>t.ToString(@"hh\:mm\:ss");
 void RefreshJob(){if(job==null)return;var s=job.Snapshot();bar.Value=(int)Math.Clamp(s.Fraction*1000,0,1000);heading.Text=$"RENDER  1 / 1　{s.Phase}　{s.Fraction:P1}";string remaining=s.Remaining.HasValue?Time(s.Remaining.Value):s.Phase=="MP4を仕上げ中"?"仕上げ処理中":"計算中";metrics.Text=$"経過 {Time(s.Elapsed)}　｜　残り {(s.Active?remaining:"—")}　｜　終了予測 {(s.Finish.HasValue?s.Finish.Value.ToString("HH:mm:ss"):"—")}";processed.Text=$"処理済み {Engine.Time(s.Processed)} / {Engine.Time(s.Total)}　｜　速度 ×{s.Speed:0.00}　｜　{s.Fps:0.0} fps　｜　{s.Bytes/1024d/1024:0.0} MB　｜　{s.Frames:N0}フレーム";settings.Text=job.Settings;destination.Text="出力先："+job.Output;failure.Text=s.Error.Length>0?"失敗："+s.Error.Split('\n').Last():"";cancel.Enabled=s.Active&&s.Phase!="キャンセル中";close.Enabled=!s.Active;if(!s.Active)timer.Stop();}
 internal RenderSnapshot? TestSnapshot=>job?.Snapshot();
 internal void TestCancel()=>cancel.PerformClick();
}
